DO $carga$
DECLARE
  paquete jsonb := $polo${"ley":{"id":"9fd0a289-5038-5d21-b98c-318784738254","siglas":"PODECOBI-CAPITAL-DE-LA-TECNOLOGIA-Y-LA-SOSTENIBILIDAD-NA1","titulo":"NOTA aclaratoria al Acuerdo por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Futura Capital de la Tecnología y la Sostenibilidad, Puebla, en los términos que se indican, publicado el 1 de julio de 2025.","tipo":"acuerdo","fecha_publicacion":"2025-07-29","url_original":"https://sidof.segob.gob.mx/notas/docFuente/5764007","temas_clave":["PODECOBI","Declaratoria","Capital de la Tecnología y la Sostenibilidad","Puebla","Nota aclaratoria"]},"articulos":[{"id":"018406fd-0341-54f2-b27f-895470690cf6","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":1,"identificador":"Preámbulo","contenido":"<p>NOTA aclaratoria al Acuerdo por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Futura Capital de la Tecnología y la Sostenibilidad, Puebla, en los términos que se indican, publicado el 1 de julio de 2025.</p>\n<p>Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Secretaría de Economía.</p>\n<p>Vidal Llerenas Morales, con fundamento en los artículos 7, fracción XIII, y 8 del Reglamento Interior de la Secretaría de Economía, y los lineamientos 3, fracción I, y 5, fracción IX del Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, se emite la siguiente:</p>\n<p>NOTA ACLARATORIA AL ACUERDO POR EL QUE SE EMITE LA DECLARATORIA DEL POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA, EN LOS TÉRMINOS QUE SE INDICAN, PUBLICADO EL 1 DE JULIO DE 2025 EN EL DIARIO OFICIAL DE LA FEDERACIÓN</p>","tipo_articulo":"preambulo","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"3b4dee1e-e730-584c-9d9f-f85c322c9099","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":2,"identificador":"Considerandos","contenido":"<p>En la página 1</p>\n<p><strong>Dice:</strong></p>\n<p>Que en la sesión del Comité Intersecretarial de Promoción celebrada el 9 de junio de 2025, fue aprobado el Dictamen Colegiado correspondiente al Polo de Desarrollo Para el Bienestar Futura Capital de la Tecnología y la Sostenibilidad, en el Estado de Puebla, en adelante POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA, y</p>\n<p><strong>Debe decir:</strong></p>\n<p>Que en la sesión del Comité Intersecretarial de Promoción celebrada el 9 de junio de 2025, fue aprobado el Dictamen Colegiado correspondiente al Polo de Desarrollo Para el Bienestar Capital de la Tecnología y la Sostenibilidad, en el Estado de Puebla, en adelante POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA, y</p>","tipo_articulo":"apartado","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"412255cb-8da6-54d3-8a7d-5bffa7c08d11","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":3,"identificador":"Denominación del acuerdo","contenido":"<p><strong>Dice:</strong></p>\n<p>ACUERDO POR EL QUE SE EMITE LA DECLARATORIA DEL POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA</p>\n<p><strong>Debe decir:</strong></p>\n<p>ACUERDO POR EL QUE SE EMITE LA DECLARATORIA DEL POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA</p>","tipo_articulo":"apartado","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"f09409d9-6a03-5f13-acd8-0f33eb07ba82","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":4,"identificador":"Artículo primero","contenido":"<p><strong>Dice:</strong></p>\n<p>ARTÍCULO PRIMERO. El presente Acuerdo tiene por objeto declarar el Polo de Desarrollo Económico para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, en el estado de Puebla.</p>\n<p><strong>Debe decir:</strong></p>\n<p>ARTÍCULO PRIMERO. El presente Acuerdo tiene por objeto declarar como Polo de Desarrollo Económico para el Bienestar Capital de la Tecnología y la Sostenibilidad, en el estado de Puebla.</p>","tipo_articulo":"apartado","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"c2d1f041-ca25-519b-b094-5cc4b64086de","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":5,"identificador":"Artículo segundo","contenido":"<p><strong>Dice:</strong></p>\n<p>ARTÍCULO SEGUNDO. Se declara como Polo de Desarrollo Económico para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA, a la superficie de 275.2 ha, ubicado en los municipios de San José Chiapa y Nopalucan, Estado de Puebla.</p>\n<p><strong>Debe decir:</strong></p>\n<p>ARTÍCULO SEGUNDO. Se declara como Polo de Desarrollo Económico para el Bienestar CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA, a la superficie de 217.68 ha, ubicadas en los municipios de San José Chiapa y Nopalucan, Estado de Puebla.</p>","tipo_articulo":"apartado","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"a19d5aee-cbb2-572d-a4e2-d8c9955ef5b3","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":6,"identificador":"Croquis y criterios de localización, conectividad y población","contenido":"<p>En la página 5</p>\n<p><strong>Dice:</strong></p>\n<p>CROQUIS DE UBICACIÓN - POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD</p>\n<p>ARTÍCULO TERCERO. ...</p>\n<p>I. Criterio de Macro Localización</p>\n<p>El inmueble del Polo de Desarrollo para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA se localiza en la región centro-oriente del estado de Puebla, una zona estratégica que articula los corredores económicos del altiplano central con el Golfo de México.</p>\n<p>Se ubica a menos de 70 km de la ciudad de Puebla y a unos 40 km del Arco Norte, lo que los conecta de manera eficiente con el Valle de México, Tlaxcala, Veracruz y el puerto de Veracruz.</p>\n<p>II. Criterio de Comunicación y Conectividad</p>\n<p>El inmueble del Polo de Desarrollo para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y SOSTENIBILIDAD, PUEBLA cuenta con una ubicación estratégica en materia de comunicación y conectividad regional, al situarse en el eje que articula el altiplano central con el Golfo de México.</p>\n<p>Este polo se encuentra cerca de la autopista Amozoc-Perote y del Arco Norte, dos corredores logísticos clave que permiten la conexión directa con el Valle de México, Veracruz, Tlaxcala y la zona metropolitana de Puebla. Esta infraestructura vial facilita el flujo eficiente de mercancías, insumos y personas, potenciando su integración a cadenas productivas regionales.</p>\n<p>III. Criterio Poblacional</p>\n<p>El Polo de Desarrollo para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA se ubica en los municipios de San José Chiapa y Nopalucan, en el estado de Puebla, cuyos municipios aledaños son: Oriental, San Salvador el Seco y Mazapiltepec de Juárez.</p>\n<p><strong>Debe decir:</strong></p>\n<p>CROQUIS DE UBICACIÓN - POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD</p>\n<p>ARTÍCULO TERCERO. ...</p>\n<p>I. Criterio de Macro Localización</p>\n<p>El inmueble del Polo de Desarrollo para el Bienestar CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA se localiza en la región centro-oriente del estado de Puebla, una zona estratégica que articula los corredores económicos del altiplano central con el Golfo de México.</p>\n<p>Se ubica a menos de 70 km de la ciudad de Puebla y a unos 40 km del Arco Norte, lo que los conecta de manera eficiente con el Valle de México, Tlaxcala, Veracruz y el puerto de Veracruz.</p>\n<p>II. Criterio de Comunicación y Conectividad</p>\n<p>El inmueble del Polo de Desarrollo para el Bienestar CAPITAL DE LA TECNOLOGÍA Y SOSTENIBILIDAD, PUEBLA cuenta con una ubicación estratégica en materia de comunicación y conectividad regional, al situarse en el eje que articula el altiplano central con el Golfo de México.</p>\n<p>Este polo se encuentra cerca de la autopista Amozoc-Perote y del Arco Norte, dos corredores logísticos clave que permiten la conexión directa con el Valle de México, Veracruz, Tlaxcala y la zona metropolitana de Puebla. Esta infraestructura vial facilita el flujo eficiente de mercancías, insumos y personas, potenciando su integración a cadenas productivas regionales.</p>\n<p>III. Criterio Poblacional</p>\n<p>El Polo de Desarrollo para el Bienestar CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA se ubica en los municipios de San José Chiapa y Nopalucan, en el estado de Puebla, cuyos municipios aledaños son: Oriental, San Salvador el Seco y Mazapiltepec de Juárez.</p>","tipo_articulo":"apartado","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"8a017e9c-48bc-5ae6-96d5-93d32420d92f","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":7,"identificador":"Factibilidad social","contenido":"<p>En la página 6:</p>\n<p><strong>Dice:</strong></p>\n<p>IV. Criterio de Factibilidad Social</p>\n<p>El Instituto Nacional de los Pueblos Indígenas mediante oficio CGDI/2025/OF/570, de fecha 5 de junio de 2025, emitió un dictamen sobre la procedencia de la consulta indígena en la superficie destinada al Polo de Desarrollo Económico para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA decretando lo siguiente:</p>\n<p><strong>Debe decir:</strong></p>\n<p>IV. Criterio de Factibilidad Social</p>\n<p>El Instituto Nacional de los Pueblos Indígenas mediante oficio CGDI/2025/OF/570, de fecha 5 de junio de 2025, emitió un dictamen sobre la procedencia de la consulta indígena en la superficie destinada al Polo de Desarrollo Económico para el Bienestar CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA decretando lo siguiente:</p>","tipo_articulo":"apartado","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"9f18be54-41f4-571b-a3a5-b79c11b142af","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":8,"identificador":"Criterio educativo","contenido":"<p><strong>Dice:</strong></p>\n<p>V. Criterio de Educativo</p>\n<p>En los municipios de San José Chiapa y Nopalucan se localizan las siguientes instituciones de educación siguientes:</p>\n<p><strong>Debe decir:</strong></p>\n<p>V. Criterio de Educativo</p>\n<p>En el municipio de San José Chiapa se localizan las siguientes instituciones de educación:</p>","tipo_articulo":"apartado","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"05fad739-0556-5848-ac7f-0c42a958855f","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":9,"identificador":"Criterio territorial","contenido":"<p><strong>Dice:</strong></p>\n<p>VI. Criterio Territorial</p>\n<p>Para el desarrollo de las actividades productivas en el Polo de Desarrollo Económico para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA son vocaciones productivas, prioritarias y potenciales las siguientes:</p>\n<p><strong>Debe decir:</strong></p>\n<p>VI. Criterio Territorial</p>\n<p>Para el desarrollo de las actividades productivas en el Polo de Desarrollo Económico para el Bienestar CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA son vocaciones productivas, prioritarias y potenciales las siguientes:</p>","tipo_articulo":"apartado","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"3408c3d5-c061-5c60-9646-a3751af0a5bf","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":10,"identificador":"Firma","contenido":"<p>Ciudad de México, a los 22 días de julio de 2025.- El Subsecretario de Industria y Comercio y Presidente del Comité Intersecretarial de Promoción, Dr. Vidal Llerenas Morales.- Rúbrica.</p>","tipo_articulo":"complementario","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Nota aclaratoria","seccion_nombre":null},{"id":"24459701-45c6-5ffe-a3e0-9d4292344085","ley_id":"9fd0a289-5038-5d21-b98c-318784738254","orden":11,"identificador":"Nota editorial · declaratoria original","tipo_articulo":"complementario","titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Documentos relacionados","seccion_nombre":null,"contenido":"<p><a href=\"#ley-53c8188a-012f-5cc3-ad7c-78be66708faa\">Texto original · ACUERDO por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Futura Capital de la Tecnología y la Sostenibilidad, Puebla.</a></p>"}]}$polo$::jsonb;
  ley jsonb := paquete->'ley';
  ley_uuid uuid := (ley->>'id')::uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(ley->>'url_original', 0));
  IF EXISTS (SELECT FROM public.leyes WHERE id <> ley_uuid AND (siglas = ley->>'siglas' OR url_original = ley->>'url_original')) THEN
    RAISE EXCEPTION 'Declaratoria registrada con otro ID: %', ley->>'siglas';
  END IF;
  INSERT INTO public.leyes (id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave)
  SELECT id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave FROM jsonb_populate_record(null::public.leyes, ley)
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.articulos (id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre)
  SELECT id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre
  FROM jsonb_populate_recordset(null::public.articulos, paquete->'articulos') ON CONFLICT (id) DO NOTHING;
  IF NOT EXISTS (SELECT FROM public.leyes l WHERE l.id = ley_uuid AND to_jsonb(l) @> ley)
     OR EXISTS (SELECT FROM jsonb_array_elements(paquete->'articulos') a WHERE NOT EXISTS (
       SELECT FROM public.articulos t WHERE t.id = (a->>'id')::uuid AND to_jsonb(t) @> a)) THEN
    RAISE EXCEPTION 'El registro existente difiere del cotejo de %', ley->>'siglas';
  END IF;
  UPDATE public.articulos SET contenido='<p>Esta ficha reproduce la declaratoria original. Consulte la publicación posterior en el DOF: <a href="https://sidof.segob.gob.mx/notas/docFuente/5764007">Nota aclaratoria del 29/07/2025</a>.</p><p><a href="#ley-9fd0a289-5038-5d21-b98c-318784738254">Nota aclaratoria en el acervo</a></p>' WHERE id='1e053ceb-c24c-5d72-843f-21bbb367c469' AND ley_id='53c8188a-012f-5cc3-ad7c-78be66708faa' AND contenido='<p>Esta ficha reproduce la declaratoria original. Consulte la publicación posterior en el DOF: <a href="https://sidof.segob.gob.mx/notas/docFuente/5764007">Nota aclaratoria del 29/07/2025</a>.</p>';
  IF NOT EXISTS (SELECT FROM public.articulos WHERE id='1e053ceb-c24c-5d72-843f-21bbb367c469' AND ley_id='53c8188a-012f-5cc3-ad7c-78be66708faa' AND contenido='<p>Esta ficha reproduce la declaratoria original. Consulte la publicación posterior en el DOF: <a href="https://sidof.segob.gob.mx/notas/docFuente/5764007">Nota aclaratoria del 29/07/2025</a>.</p><p><a href="#ley-9fd0a289-5038-5d21-b98c-318784738254">Nota aclaratoria en el acervo</a></p>') THEN
    RAISE EXCEPTION 'La guía de la declaratoria original difiere del cotejo';
  END IF;
END
$carga$;
